var n=`0864-nihari`;var a=`world-0864`;var t=`PK`;var s=`south-asia`;var o=4;var r=235;var g={en:`Nihari`,ua:`Ніхарі`};var h={en:`Nihari is a Pakistan dish made with beef shank, yellow onion, ginger-garlic paste, whole wheat flour. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Ніхарі, страва кухні країни Пакистан. Основні складники: яловича гомілка, жовта цибуля, імбирно-часникова паста, цільнозернове пшеничне борошно. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 13 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 13 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:13,i:[[`beef-shank`,1050,`g`],[`ghee`,65,`g`],[`yellow-onion`,220,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`ginger-garlic-paste`,35,`g`],[`kashmiri-chili-powder`,8,`g`],[`ground-coriander`,7,`g`],[`ground-cumin`,5,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 210 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 210 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:210,i:[[`beef-stock`,1e3,`ml`],[`whole-wheat-flour`,30,`g`],[`garam-masala`,9,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`ground-ginger`,18,`g`],[`cilantro`,18,`g`],[`lemon`,1,`pcs`]]}];var d={slug:n,id:a,country:`PK`,region:s,servings:4,minutes:235,title:g,text:h,steps:l};export{t as country,d as default,a as id,r as minutes,s as region,o as servings,n as slug,l as steps,h as text,g as title};